def f(g):
    W=len(g[0]); S=None
    for c,x in enumerate(g[0]):
        if x==2: S=c
    H=W  # square output assumed
    out=[[0]*W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            if r+c==S or c-r==S:
                out[r][c]=2
            elif (c-r-S)%4==0 and c-r<S and r+c>S:
                out[r][c]=1
    return out
